-- ── PRECONDITION: nothing still reads the columns this file drops ──
do $$
begin
  if exists (select 1 from pg_proc p where p.pronamespace = 'public'::regnamespace
              and p.proname in ('hr_hunt_member_read', 'hr_hunt_settle_session')
              and (p.prosrc like '%q.tiers%' or p.prosrc like '%b.tiers%' or p.prosrc like '%v_tier%')) then
    raise exception 'PRECONDITION: apply 2026-11-07-store-by-slot.sql first (a hunt body still reads the store tier)'; end if;
  if exists (select 1 from pg_proc p where p.pronamespace = 'public'::regnamespace
              and p.proname in ('hr_char_level', 'hr_char_xp_for_level') and p.prosrc like '%level_quartic%')
     or to_regclass('public.hr_level_curve') is null then
    raise exception 'PRECONDITION: apply 2027-02-01-level-curve.generated.sql first (a Level curve function still reads hr_hunt_limits)'; end if;
  if exists (select 1 from pg_proc p where p.pronamespace = 'public'::regnamespace and p.prosrc like '%death_xp_base%') then
    raise exception 'PRECONDITION: apply 2027-03-25-death-share.sql first (a hunt body still reads hr_hunt_limits.death_xp_base)'; end if;
end $$;
--
-- Server-only: RLS on, NO policy, no client grant (the client reads src/data).
-- Idempotent: delete + insert; nothing references these rows by foreign key.
-- No begin/commit (CLAUDE.md §2).
-- ════════════════════════════════════════════════════════════════════════

create table if not exists public.hr_hunt_supplies (
  item_id   text primary key check (item_id ~ '^[a-z0-9_]{1,64}$'),
  kind      text not null check (kind in ('heal', 'mana', 'buff', 'ammo')),
  essential boolean not null,
  heals     int  not null check (heals >= 0),
  buff_type text,
  constraint hr_hunt_supplies_shape_ck check (
    (kind = 'heal' and heals > 0 and buff_type is null)
    or (kind = 'mana' and heals = 0 and buff_type is null)
    or (kind = 'buff' and heals = 0 and buff_type is not null)
    or (kind = 'ammo' and heals = 0 and buff_type is null))
);
-- An existing table (created by an applied catalogue) learns kind 'mana'.
alter table public.hr_hunt_supplies drop constraint if exists hr_hunt_supplies_kind_check;
alter table public.hr_hunt_supplies add constraint hr_hunt_supplies_kind_check check (kind in ('heal', 'mana', 'buff', 'ammo'));
alter table public.hr_hunt_supplies drop constraint if exists hr_hunt_supplies_shape_ck;
alter table public.hr_hunt_supplies add constraint hr_hunt_supplies_shape_ck check (
    (kind = 'heal' and heals > 0 and buff_type is null)
    or (kind = 'mana' and heals = 0 and buff_type is null)
    or (kind = 'buff' and heals = 0 and buff_type is not null)
    or (kind = 'ammo' and heals = 0 and buff_type is null));
create table if not exists public.hr_hunt_travel (
  hunt_id  text primary key check (hunt_id ~ '^[a-z0-9_]{1,64}$'),
  travel_s int  not null check (travel_s between 0 and 300 and travel_s % 10 = 0),
  training boolean not null
);
-- An existing table (created by an applied catalogue) learns a walk of 0.
alter table public.hr_hunt_travel drop constraint if exists hr_hunt_travel_travel_s_check;
alter table public.hr_hunt_travel add constraint hr_hunt_travel_travel_s_check check (travel_s between 0 and 300 and travel_s % 10 = 0);
-- THE STORE TIER is unread (Tyler 2026-10-19: the player's slot picks the store item;
-- 2026-11-07-store-by-slot.sql restated its last readers before this file). Its two columns
-- stay, written null / empty, only because the applied 2026-10-27-core-bodies.sql re-creates a
-- LANGUAGE sql reader of them whenever it is replayed (tests/hunts-c1.mjs C1): a dropped
-- column would make that history unreplayable. No row carries a tier (the self-check below).
alter table public.hr_hunt_travel add column if not exists tier int;
-- THE SPAWN CYCLE of the single-foe engine lived here (pull_size, respawn_ms);
-- a hunt's cycle is its GROUND now (hr_hunt_grounds, the world's packs).
alter table public.hr_hunt_travel drop column if exists pull_size;
alter table public.hr_hunt_travel drop column if exists respawn_ms;
create table if not exists public.hr_hunt_limits (
  key   text primary key check (key ~ '^[a-z0-9_]{1,64}$'),
  value int  not null check (value between 0 and 100000)
);
create table if not exists public.hr_hunt_end_reasons (
  reason text primary key check (reason ~ '^[a-z0-9_]{1,64}$'),
  ord    int  not null unique check (ord >= 1)
);
alter table public.hr_hunt_end_reasons add column if not exists resumes boolean not null default false;
create table if not exists public.hr_hunt_vendor_value (
  item_id text primary key check (item_id ~ '^[a-z0-9_]{1,64}$'),
  unit    bigint not null check (unit >= 1)
);
create table if not exists public.hr_hunt_basic_supplies (
  basic_id text primary key check (basic_id ~ '^[a-z0-9_]{1,64}$'),
  kind     text not null check (kind in ('heal', 'mana', 'ammo')),
  partner  text not null check (partner ~ '^[a-z0-9_]{1,64}$'),
  heals    int  not null check (heals >= 0),
  mana     int  not null check (mana >= 0),
  price    bigint not null check (price between 1 and 1000000000)
);
alter table public.hr_hunt_basic_supplies add column if not exists tiers int[];
alter table public.hr_hunt_basic_supplies alter column tiers set default '{}'::int[];
create table if not exists public.hr_hunt_cover_items (
  item_id text primary key check (item_id ~ '^[a-z0-9_]{1,64}$'),
  unit    bigint not null check (unit >= 1)
);
create table if not exists public.hr_hunt_target_modes (
  mode text primary key check (mode ~ '^[a-z0-9_]{1,64}$')
);
-- A solo hunt is a party of one: no mode is party-only any more.
alter table public.hr_hunt_target_modes drop column if exists solo;
create table if not exists public.hr_hunt_resumable_kinds (
  kind text primary key check (kind ~ '^[a-z0-9_]{1,64}$')
);
-- THE LANES: food and drink share ONE (consumables.js laneMs); the ability lanes
-- are abilities.js'. The settle's use caps read their ms from HERE.
create table if not exists public.hr_hunt_lanes (
  lane   text primary key check (lane ~ '^[a-z0-9_]{1,64}$'),
  ms     int check (ms is null or ms > 0),
  active boolean not null,
  check (active = (ms is not null))
);
create table if not exists public.hr_hunt_kill_bounds (
  monster_id text primary key check (monster_id ~ '^[a-z0-9_]{1,64}$'),
  gold_max   bigint not null check (gold_max >= 0),
  xp_max     bigint not null check (xp_max >= 1),
  drops      jsonb  not null check (jsonb_typeof(drops) = 'object')
);
create table if not exists public.hr_hunt_set_options (
  opt       text primary key check (opt ~ '^[a-z0-9_]{1,64}$'),
  kind      text not null,
  limit_key text check (limit_key is null or limit_key ~ '^[a-z0-9_]{1,64}$'),
  vals      text[],
  check ((kind = 'limit') = (limit_key is not null)),
  check ((kind = 'enum') = (vals is not null)),
  dflt      jsonb
);
-- The value an unset option takes (null = the role's default for its party).
alter table public.hr_hunt_set_options add column if not exists dflt jsonb;
-- A per-hero switch is an option too (chase on / off): kind 'bool'.
alter table public.hr_hunt_set_options drop constraint if exists hr_hunt_set_options_kind_check;
alter table public.hr_hunt_set_options add constraint hr_hunt_set_options_kind_check
  check (kind in ('target', 'limit', 'enum', 'bool'));
-- THE BAR'S VOCABULARY (abilities.js): what an action set's bar may hold.
create table if not exists public.hr_hunt_abilities (
  ability_id  text primary key check (ability_id ~ '^[a-z0-9_]{1,64}$'),
  disciplines text[] not null check (cardinality(disciplines) >= 1),
  lane        text not null check (lane ~ '^[a-z0-9_]{1,64}$'),
  cd_ms       int  not null check (cd_ms > 0),
  mana        int  not null check (mana >= 0),
  rune        text check (rune is null or rune ~ '^[a-z0-9_]{1,64}$'),
  ammo        int  not null check (ammo >= 0),
  active      boolean not null,
  ord         int  not null default 0 check (ord >= 0)
);
alter table public.hr_hunt_abilities add column if not exists ord int not null default 0;
-- A universal row (the self-heal Mend) names every discipline (abilities.js DISCIPLINES, seven since the club and the
-- sword alone have their own lists): no fixed cap on how many disciplines share a row.
alter table public.hr_hunt_abilities drop constraint if exists hr_hunt_abilities_disciplines_check;
alter table public.hr_hunt_abilities add constraint hr_hunt_abilities_disciplines_check check (cardinality(disciplines) >= 1);
-- RETIRED (lane b-spell-roles, 2027-01-13): a role named ONE ability discipline. A role is now played by several role
-- keys on their own lists (hr_hunt_weapon_roles.discipline); 2027-01-13-spell-roles.sql restates its last reader,
-- hr_hunt_settings_view. Kept, EMPTY, because applied history's §0 checks and bodies name it.
create table if not exists public.hr_hunt_roles (
  role       text primary key check (role ~ '^[a-z0-9_]{1,64}$'),
  discipline text not null check (discipline ~ '^[a-z0-9_]{1,64}$')
);
-- WHERE A HUNT IS FOUGHT (hunt-grounds.js): a hunt with no row here cannot be
-- entered (no_ground) and its settle has nothing to step. The spawns bound the
-- kills a window can carry (hr_hunt_apply_member).
create table if not exists public.hr_hunt_grounds (
  hunt_id    text primary key check (hunt_id ~ '^[a-z0-9_]{1,64}$'),
  ground_id  text not null unique check (ground_id ~ '^[a-z0-9_]{1,40}$'),
  pockets    int  not null check (pockets between 1 and 64),
  spawns     int  not null check (spawns between 1 and 256),
  respawn_ms int  not null check (respawn_ms between 1000 and 600000),
  seats      int  not null check (seats between 1 and 5)
);
-- THE MOST DENSITY A HERO MAY PICK HERE, one entry per party size 1..n (hunt-grounds.js densityFor):
-- hr_hunt_density_set refuses a pick over the largest; the instance's freeze clamps to it. Every row
-- carries it (the check block below); an existing table learns the column.
alter table public.hr_hunt_grounds add column if not exists density_max int[];
alter table public.hr_hunt_grounds drop constraint if exists hr_hunt_grounds_density_max_ck;
alter table public.hr_hunt_grounds add constraint hr_hunt_grounds_density_max_ck check (density_max is null
  or (cardinality(density_max) between 1 and 8 and array_position(density_max, null) is null
      and 0 <= all (density_max) and 16 >= all (density_max)));
-- THE LEVEL THE GROUND IS OUTGROWN AT (hunt-grounds.js endsAtLevel; END_ORDER's outgrown), null on a ground with none: the door refuses a
-- hero at it (hr_hunt_admit) and the settle proves the end by it (hr_hunt_settle_session), 2027-05-28-cellar-outgrown.sql.
alter table public.hr_hunt_grounds add column if not exists ends_at_level int;
alter table public.hr_hunt_grounds drop constraint if exists hr_hunt_grounds_ends_at_level_ck;
alter table public.hr_hunt_grounds add constraint hr_hunt_grounds_ends_at_level_ck check (ends_at_level is null or ends_at_level between 2 and 10000);
create table if not exists public.hr_hunt_ground_spawns (
  hunt_id    text not null references public.hr_hunt_grounds (hunt_id) on delete cascade,
  monster_id text not null check (monster_id ~ '^[a-z0-9_]{1,64}$'),
  n          int  not null check (n between 1 and 256),
  primary key (hunt_id, monster_id)
);
-- THE WORLD'S SHAPE (world-state.js): the version and field-list fingerprint
-- every encoded hunt_instances.world must carry.
-- THE REACHABLE ROSTER (hunt-grounds.js reachableOf over the open grounds): every monster a player can meet. The
-- Bestiary's total counts only these.
create table if not exists public.hr_hunt_roster (
  monster_id text primary key check (monster_id ~ '^[a-z0-9_]{1,64}$')
);
create table if not exists public.hr_hunt_world_shape (
  id      boolean primary key default true check (id),
  version int    not null check (version >= 1),
  shape   bigint not null check (shape between 0 and 4294967295),
  fields  jsonb  not null default '{}'::jsonb check (jsonb_typeof(fields) = 'object')
);
alter table public.hr_hunt_world_shape add column if not exists fields jsonb not null default '{}'::jsonb;
-- THE PREMIUM DAILY LOGIN REWARD (premium.js): the item a claim pays (null =
-- nothing yet) and how many.
create table if not exists public.hr_premium_login_reward (
  id      boolean primary key default true check (id),
  item_id text check (item_id is null or item_id ~ '^[a-z0-9_]{1,64}$'),
  qty     int  not null check (qty between 1 and 10)
);
-- WHAT A WEAPON MAKES A HERO (hunt-roles.js WEAPON_ROLES): each weapon's type,
-- and the roles a type plays, the first the default.
create table if not exists public.hr_hunt_weapons (
  item_id     text primary key check (item_id ~ '^[a-z0-9_]{1,64}$'),
  weapon_type text not null check (weapon_type ~ '^[a-z0-9_]{1,32}$')
);
create table if not exists public.hr_hunt_weapon_roles (
  weapon_type text primary key check (weapon_type ~ '^[a-z0-9_]{1,32}$'),
  roles       text[] not null check (cardinality(roles) between 1 and 5)
);
-- EACH KEY'S ABILITY DISCIPLINE (abilities.js DISCIPLINES) and SHIELD ARM (hunt-roles.js SHIELD_ARM: the key a worn
-- shield turns it into, null = it keeps its own and gains only the shield's guard). Every row carries a discipline (the
-- self-check below); an existing table learns both columns.
alter table public.hr_hunt_weapon_roles add column if not exists discipline text;
alter table public.hr_hunt_weapon_roles add column if not exists with_shield text;
alter table public.hr_hunt_weapon_roles drop constraint if exists hr_hunt_weapon_roles_discipline_ck;
alter table public.hr_hunt_weapon_roles add constraint hr_hunt_weapon_roles_discipline_ck check (discipline is null or discipline ~ '^[a-z0-9_]{1,64}$');
alter table public.hr_hunt_weapon_roles drop constraint if exists hr_hunt_weapon_roles_with_shield_ck;
alter table public.hr_hunt_weapon_roles add constraint hr_hunt_weapon_roles_with_shield_ck check (with_shield is null or with_shield ~ '^[a-z0-9_]{1,32}$');
-- THE SHIELDS (shields.js isShield): the off-hand items a shield arm reads (hr_hunt_weapon_of).
create table if not exists public.hr_hunt_shields (
  item_id text primary key check (item_id ~ '^[a-z0-9_]{1,64}$')
);
-- CALL OUT, THE MONEY LINE AS A CHECK: a normal monster's XP bound stays at least 1 (a 0 refuses every kill of it), and a called row pays no XP or coin (a called boss's drops are his win's, Tyler 2026-11-14). The id tells them apart (calledRows holds id and flag equal).
alter table public.hr_hunt_kill_bounds drop constraint if exists hr_hunt_kill_bounds_xp_max_check;
alter table public.hr_hunt_kill_bounds add constraint hr_hunt_kill_bounds_xp_max_check
  check ((monster_id !~ '_called$' and xp_max >= 1) or (monster_id ~ '_called$' and xp_max = 0 and gold_max = 0));
-- CALL OUT (boss-calls.js): which rooms, what fee. Read by hr_hunt_admit, hr_boss_call and the settle's proof of the room's ends.
create table if not exists public.hr_boss_calls (
  call_id    text   primary key check (call_id ~ '^[a-z0-9_]{1,64}$'),
  hunt_id    text   not null unique check (hunt_id ~ '^[a-z0-9_]{1,57}_called$'),
  from_hunt  text   not null check (from_hunt ~ '^[a-z0-9_]{1,64}$'),
  monster_id text   not null check (monster_id ~ '^[a-z0-9_]{1,64}$'),
  limit_ms   int    not null check (limit_ms between 60000 and 3600000),
  fight_fee  bigint not null,
  fight_stamina_ms int not null,
  max_fights int    not null,
  drops      jsonb  not null,
  boss_level int    not null
);
-- A HERO ALONE MAY CALL (2027-04-05-call-out-alone.sql restates the quote that read it first): no party size.
alter table public.hr_boss_calls drop column if exists party_min;
-- THE SERIES (Tyler 2026-11-14: a slider of fights, each costing stamina and a small fee; no daily cap): one fight's price and the slider's top.
-- The one-fight verb's fee and daily cap go. 2027-04-24-boss-call-series.sql restates every reader of them and applies RIGHT AFTER this file.
alter table public.hr_boss_calls add column if not exists fight_fee bigint, add column if not exists fight_stamina_ms int, add column if not exists max_fights int;
-- WHAT A WIN CAN DROP, for the page (audit F24): his table in its order, [{ item, ppm (odds in parts per million), band }], from monsters.js.
alter table public.hr_boss_calls add column if not exists drops jsonb, add column if not exists boss_level int;
alter table public.hr_boss_calls drop column if exists fee, drop column if exists per_day;
-- NATURAL WINS BEFORE THE CALL (lane/c-entry-gates; Tyler 2026-11-18): the boss the call copies (his kills on his ground are the count) and how many it needs.
alter table public.hr_boss_calls add column if not exists boss_id text, add column if not exists wins int;
comment on table public.hr_boss_calls is
  'tools/gen-hunt-sessions.mjs from src/data/boss-calls.js: the called rooms, one fight''s price (stamina; its gold is 0, Tyler 2026-11-20) and the most fights one series may queue (Call out). Names no player; character wipe c_no_player.';
-- COMBAT TRAINING (training.js): the rules, one row, each training ground's place, skill and fee, and the training items. Read by hr_training_start,
-- the settle's hourly charge (hr_training_hour), its window check and the items' spend (hr_training_window), the items' verbs and the section
-- (2027-04-16-combat-training.sql, 2027-04-23-training-gear.sql).
create table if not exists public.hr_training_rules (
  id            boolean primary key default true check (id),
  fee_base      int     not null check (fee_base >= 0),
  fee_per_level int     not null check (fee_per_level >= 0),
  hp_floor_pm   int     not null check (hp_floor_pm between 1 and 999),
  max_hours     int     not null check (max_hours between 1 and 24),
  house_tier    int     not null check (house_tier >= 1),
  house_tier_id text    not null check (house_tier_id ~ '^[a-z0-9_]{1,32}$'),
  constraint hr_training_rules_fee_ck check (fee_base + fee_per_level > 0)
);
-- THE FIXED RATE AND THE ITEMS (lane/c-training-gear): the table an earlier revision of this file made widens here, nullable until the row below
-- fills it, then NOT NULL (the same shape however the table was made).
alter table public.hr_training_rules
  add column if not exists xp_per_hour int check (xp_per_hour between 1 and 1000000),
  add column if not exists min_level   int check (min_level between 1 and 200),
  add column if not exists boost_pm    int check (boost_pm between 1001 and 10000),
  add column if not exists buy_per_day int check (buy_per_day between 1 and 100);
create table if not exists public.hr_training_grounds (
  hunt_id     text    primary key check (hunt_id ~ '^[a-z0-9_]{1,64}$'),
  place       text    not null check (place in ('yard', 'house')),
  skill       text    not null check (skill ~ '^[a-z0-9_]{1,64}$'),
  ord         int     not null check (ord >= 0),
  fee         boolean not null,
  constraint hr_training_grounds_place_skill unique (place, skill),
  constraint hr_training_grounds_fee_ck check (fee = (place = 'yard'))
);
-- THE PAY IS THE TIME (Tyler 2026-11-14): the per-skill share of a blow is gone (2027-04-23-training-gear.sql restates the bodies that read it).
alter table public.hr_training_grounds drop column if exists xp_permille;
-- THE TRAINING ITEMS (training.js TRAINING_GEAR): each item's skill, its hours (ms), whether it is the Crowns store's bound copy, and the Arms
-- Master's gold price (null for a bound row: no gold door sells it). The items themselves are hr_items rows (tools/gen-catalogues.mjs).
create table if not exists public.hr_training_gear (
  item_id  text    primary key check (item_id ~ '^[a-z0-9_]{1,64}$'),
  skill    text    not null check (skill ~ '^[a-z0-9_]{1,64}$'),
  hours_ms bigint  not null check (hours_ms between 3600000 and 172800000),
  bound    boolean not null,
  price    bigint  check (price between 1 and 1000000000),
  constraint hr_training_gear_price_ck check ((price is null) = bound)
);
comment on table public.hr_training_gear is
  'tools/gen-hunt-sessions.mjs from src/data/training.js TRAINING_GEAR: the training items, their skill, hours, bound flag and gold price (lane/c-training-gear). Names no player; character wipe c_no_player.';
comment on table public.hr_training_rules is
  'tools/gen-hunt-sessions.mjs from src/data/training.js: the training rate and the Level it starts at, an item''s rate, the yard''s fee, the dummy''s floor, the longest session, the house dummy''s property tier, the Arms Master''s day clamp (lane/c-combat-training, lane/c-training-gear). Names no player; character wipe c_no_player.';
comment on table public.hr_training_grounds is
  'tools/gen-hunt-sessions.mjs from src/data/training.js and hunt-grounds.js TRAINING_GROUNDS: each training ground''s place, trained skill and hourly fee (lane/c-combat-training). Names no player; character wipe c_no_player.';
-- KEYED HALLS (boss-halls.js): which room a Hall Key opens, the boss whose kill ends it, the key it spends and its limit. Read by hr_hunt_admit,
-- hr_boss_hall_enter and the settle's proof of the room's ends (2027-04-20-boss-hall.sql). A hall's room is its ground's id and _hall.
create table if not exists public.hr_boss_halls (
  hall_id    text not null primary key check (hall_id ~ '^[a-z0-9_]{1,59}$'),
  hunt_id    text not null unique,
  monster_id text not null check (monster_id ~ '^[a-z0-9_]{1,64}$' and monster_id !~ '_called$'),
  key_item   text not null check (key_item ~ '^[a-z0-9_]{1,64}$'),
  limit_ms   int  not null check (limit_ms between 60000 and 3600000),
  constraint hr_boss_halls_hunt_ck check (hunt_id = hall_id || '_hall')
);
comment on table public.hr_boss_halls is
  'tools/gen-hunt-sessions.mjs from src/data/boss-halls.js: the keyed halls, the key each spends and its limit (lane/b-barrow-boss-room). Names no player; character wipe c_no_player.';
do $$
declare v_t text;
begin
  foreach v_t in array array['hr_hunt_supplies', 'hr_hunt_travel', 'hr_hunt_limits', 'hr_hunt_end_reasons', 'hr_hunt_vendor_value', 'hr_hunt_target_modes', 'hr_hunt_resumable_kinds', 'hr_hunt_basic_supplies', 'hr_hunt_cover_items', 'hr_hunt_lanes', 'hr_hunt_set_options', 'hr_hunt_kill_bounds', 'hr_hunt_abilities', 'hr_hunt_grounds', 'hr_hunt_ground_spawns', 'hr_hunt_world_shape', 'hr_premium_login_reward', 'hr_hunt_roster', 'hr_hunt_weapons', 'hr_hunt_weapon_roles', 'hr_hunt_roles', 'hr_hunt_shields', 'hr_boss_calls', 'hr_training_rules', 'hr_training_grounds', 'hr_boss_halls', 'hr_training_gear'] loop
    execute format('alter table public.%I enable row level security', v_t);
    execute format('revoke all on public.%I from public, anon, authenticated, service_role', v_t);
  end loop;
end $$;

