delete from public.hr_boss_calls;
-- the price's CHECK is restated below; it goes first, so a row the new one allows (a fight at 0 gold, Tyler 2026-11-20) is never judged by the old
alter table public.hr_boss_calls drop constraint if exists hr_boss_calls_fight_ck;
insert into public.hr_boss_calls (call_id, hunt_id, from_hunt, monster_id, limit_ms, fight_fee, fight_stamina_ms, max_fights, drops, boss_level, boss_id, wins) values
  ('chief_coppercap', 'coppercap_warrens_called', 'coppercap_warrens', 'chief_coppercap_called', 600000, 0, 150000, 100, '[{"item":"big_bones","ppm":1000000,"band":"common"},{"item":"gold_ore","ppm":480000,"band":"common"},{"item":"goblin_totem","ppm":288000,"band":"common"},{"item":"coppercaps_tallow","ppm":144000,"band":"uncommon"},{"item":"steel_platebody","ppm":42200,"band":"scarce"},{"item":"boarhide_body","ppm":42200,"band":"scarce"},{"item":"scholar_body","ppm":42200,"band":"scarce"},{"item":"coppercap_shield","ppm":42200,"band":"scarce"},{"item":"war_crown","ppm":13500,"band":"rare"},{"item":"willow_wand","ppm":11000,"band":"rare"},{"item":"willow_spellbook","ppm":11000,"band":"rare"},{"item":"willow_staff","ppm":11000,"band":"rare"},{"item":"verdigris_cake","ppm":11000,"band":"rare"},{"item":"coppercaps_cauldron","ppm":1270,"band":"trophy"},{"item":"cauldron_lid","ppm":8000,"band":"rare"}]'::jsonb, 52, 'chief_coppercap', 10),
  ('rat_king', 'millrace_sewer_called', 'millrace_sewer', 'rat_king_called', 600000, 0, 120000, 100, '[{"item":"rat_tail","ppm":1000000,"band":"common"},{"item":"bones","ppm":1000000,"band":"common"},{"item":"knotted_tails","ppm":150000,"band":"uncommon"},{"item":"crown_shard","ppm":14000,"band":"rare"},{"item":"kingsgrate","ppm":16000,"band":"rare"},{"item":"rat_kings_knot","ppm":14000,"band":"rare"},{"item":"rat_kings_crown","ppm":1480,"band":"trophy"},{"item":"kingstooth","ppm":10000,"band":"rare"}]'::jsonb, 25, 'rat_king', 10);
alter table public.hr_boss_calls alter column fight_fee set not null, alter column fight_stamina_ms set not null, alter column max_fights set not null, alter column drops set not null,
  alter column boss_level set not null, alter column boss_id set not null, alter column wins set not null;
alter table public.hr_boss_calls drop constraint if exists hr_boss_calls_fight_ck;
alter table public.hr_boss_calls add constraint hr_boss_calls_fight_ck
  check (fight_fee between 0 and 1000000000 and fight_stamina_ms between 1000 and 3600000 and max_fights between 1 and 1000
         and jsonb_typeof(drops) = 'array' and jsonb_array_length(drops) between 1 and 32 and boss_level between 1 and 999);
-- NATURAL WINS BEFORE THE CALL: a whole count, on a ground boss's own id (never a called row's: those wins are the call's, not the ground's).
alter table public.hr_boss_calls drop constraint if exists hr_boss_calls_wins_ck;
alter table public.hr_boss_calls add constraint hr_boss_calls_wins_ck
