-- ── SELF-CHECK (CLAUDE.md §4): the rows the generator wrote, and nothing more ──
do $$
declare v_role text; v_t text;
begin
  if (select count(*) from public.hr_hunt_supplies) <> 81
     or (select count(*) from public.hr_hunt_travel) <> 168
     or (select count(*) from public.hr_hunt_limits) <> 48
     or (select count(*) from public.hr_hunt_end_reasons) <> 18
     or (select count(*) from public.hr_hunt_vendor_value) <> 729
     or (select count(*) from public.hr_hunt_basic_supplies) <> 49
     or (select count(*) from public.hr_hunt_cover_items) <> 0
     or exists (select 1 from public.hr_hunt_basic_supplies where cardinality(coalesce(tiers, '{}'::int[])) > 0)
     or exists (select 1 from public.hr_hunt_travel where tier is not null)
     or (select count(*) from public.hr_hunt_target_modes) <> 5
     or (select count(*) from public.hr_hunt_resumable_kinds) <> 3
     or (select count(*) from public.hr_hunt_lanes) <> 4
     or (select count(*) from public.hr_hunt_set_options) <> 10
     or (select count(*) from public.hr_hunt_kill_bounds) <> 170
     or (select count(*) from public.hr_hunt_abilities) <> 25
     or (select count(*) from public.hr_hunt_grounds) <> 25
     or (select count(*) from public.hr_hunt_grounds where density_max is null) <> 0
     or (select count(*) from public.hr_hunt_ground_spawns) <> 70
     or (select count(*) from public.hr_hunt_roster) <> 55
     or (select count(*) from public.hr_hunt_world_shape) <> 1
     or (select count(*) from public.hr_premium_login_reward) <> 1
     or (select count(*) from public.hr_hunt_weapons) <> 106
     or (select count(*) from public.hr_hunt_weapon_roles) <> 12
     or (select count(*) from public.hr_hunt_roles) <> 0
     or (select count(*) from public.hr_hunt_shields) <> 14
     or (select count(*) from public.hr_boss_calls) <> 2
     or (select count(*) from public.hr_training_rules) <> 1
     or (select count(*) from public.hr_training_grounds) <> 8
     or (select count(*) from public.hr_training_gear) <> 16
     or (select count(*) from public.hr_boss_halls) <> 1
     or exists (select 1 from public.hr_hunt_weapon_roles where discipline is null)
     or exists (select 1 from public.hr_hunt_weapon_roles w where w.with_shield is not null
                 and not exists (select 1 from public.hr_hunt_weapon_roles k where k.weapon_type = w.with_shield))
     or (select count(*) from public.hr_hunt_end_reasons where resumes) <> 16 then
    raise exception 'hunt-session catalogue row counts moved from the generator''s'; end if;
  -- Every ground's outgrown Level is the data's (hunt-grounds.js endsAtLevel; the door and the settle's proof read it), null where it has none.
  if (select count(*) from public.hr_hunt_grounds where ends_at_level is not null) <> 1
     or exists (select 1 from public.hr_hunt_grounds g where g.ends_at_level is not null and (g.ground_id, g.ends_at_level) not in
               (('mill_cellar', 5))) then
    raise exception 'a hunt ground''s ends_at_level is not hunt-grounds.js endsAtLevel'; end if;
  -- Every ground's respawn is the data's (the settle's kill bound reads it: 2027-02-09, the Cellar at 32 s).
  if exists (select 1 from public.hr_hunt_grounds g where (g.ground_id, g.respawn_ms) not in
               (('coppercap_warrens', 90000), ('coppercap_warrens_called', 600000), ('hasks_ford', 60000), ('krells_hold', 60000), ('krells_hold_hall', 600000), ('meadowbrook_thicket', 60000), ('mill_cellar', 32000), ('millrace_sewer', 90000), ('millrace_sewer_called', 600000), ('mosslight_glade', 60000), ('muster_barrows', 90000), ('pyre_field', 60000), ('the_burning_tower', 4000), ('the_slake', 60000), ('training_house_defense', 10000), ('training_house_magic', 10000), ('training_house_melee', 10000), ('training_house_ranged', 10000), ('training_yard_defense', 10000), ('training_yard_magic', 10000), ('training_yard_melee', 10000), ('training_yard_ranged', 10000), ('unmarked_bone_wing', 4000), ('unmarked_flooded_wing', 4000), ('wickstead', 60000))) then
    raise exception 'a hunt ground''s respawn_ms is not hunt-grounds.js respawnMs'; end if;
  -- THE KILL BOUND'S BASE is the room as built for every group (Tyler 2026-11-11): every ground's spawns, as generated.
  if exists (select 1 from public.hr_hunt_grounds g where (g.ground_id, g.pockets, g.spawns) not in
               (('coppercap_warrens', 6, 18), ('coppercap_warrens_called', 1, 4), ('hasks_ford', 6, 12), ('krells_hold', 5, 10), ('krells_hold_hall', 1, 4), ('meadowbrook_thicket', 6, 13), ('mill_cellar', 2, 5), ('millrace_sewer', 6, 19), ('millrace_sewer_called', 1, 4), ('mosslight_glade', 6, 13), ('muster_barrows', 7, 23), ('pyre_field', 6, 12), ('the_burning_tower', 1, 5), ('the_slake', 6, 12), ('training_house_defense', 1, 1), ('training_house_magic', 1, 1), ('training_house_melee', 1, 1), ('training_house_ranged', 1, 1), ('training_yard_defense', 1, 1), ('training_yard_magic', 1, 1), ('training_yard_melee', 1, 1), ('training_yard_ranged', 1, 1), ('unmarked_bone_wing', 1, 5), ('unmarked_flooded_wing', 1, 5), ('wickstead', 6, 12))) then
    raise exception 'a hunt ground''s spawns is not its rows as built (no party pull on Normal)'; end if;
  -- The world fields the party section reads by name are all there, at the generator's positions.
  if (select fields from public.hr_hunt_world_shape) is distinct from '{"unit":{"id":0,"side":1,"kind":2,"pocket":3,"alive":4,"hp":5,"maxHp":6,"target":7,"home":8,"x":9,"y":10,"fx":11,"fy":12,"prog":13,"speed":14,"dir":15,"goal":16,"path":17,"waitMs":18,"repathMs":19,"spot":20,"holdMs":21,"role":22,"dist":23,"chase":24,"tmode":25,"queued":26,"aiMs":27,"deadMs":28,"hpMilli":29,"stance":30,"acc":31,"maxHit":32,"def":33,"element":34,"swingLeftMs":35,"spellCds":36,"cast":37,"mana":38,"maxMana":39,"manaMilli":40,"regenPm":41,"lanes":42,"cds":43,"shield":44,"shieldBy":45,"markPm":46,"markUntil":47,"lastMove":48,"statuses":49,"laneAt":50,"otHp":51,"otMana":52,"ruleHold":53,"ruleWait":54,"fightMs":55,"took":56},"world":{"ground":0,"swing":1,"leader":2,"trail":3,"leaderLast":4,"hold":5,"holdNext":6,"phase":7,"routeIdx":8,"phaseMs":9,"regroupNext":10,"runs":11,"nextId":12,"density":13,"fightAt":14,"xpGroup":15,"rareWon":16,"risk":17,"danger":18,"climb":19,"clean":20,"low":21,"cool":22,"lowHero":23,"lowBy":24}}'::jsonb
     or exists (select 1 from unnest(array['id', 'side', 'kind', 'alive', 'x', 'y', 'hp', 'maxHp', 'target', 'mana', 'maxMana', 'shield', 'otHp', 'otMana', 'role', 'dist', 'chase', 'tmode', 'stance']) n
                 where not ((select fields->'unit' from public.hr_hunt_world_shape) ? n)) then
    raise exception 'hr_hunt_world_shape.fields is not world-state.js FIELDS'; end if;
  -- ONE consumable lane, at the data file's ms (the food-lane ruling, spec §3.4 #3).
  if (select ms from public.hr_hunt_lanes where lane = 'consumable') is distinct from 2000 then
    raise exception 'the consumable lane is not consumables.js laneMs'; end if;
  -- Premium may never rest less than free; the core model's curves are live (a Level and a skill both start at 0 XP:
  -- the Level curve's own rows, hr_level_curve, and the skill curve's base).
  if public.hr_hunt_limit('stamina_premium_min') < public.hr_hunt_limit('stamina_free_min')
     or public.hr_hunt_limit('level_cubic') is not null
     or coalesce(public.hr_char_xp_for_level(2), 0) <= 0 or coalesce(public.hr_hunt_limit('skill_base'), 0) <= 0
     or coalesce(public.hr_hunt_limit('armour_slots'), 0) <= 0 then
    raise exception 'the stamina caps or the core model rows are malformed'; end if;
  -- THE DEFENSE BOUND HOLDS A MONSTER'S SPELL (2027-04-15, area spells). hr_hunt_apply_member prices every foe at one block every swing
  -- interval. A spell's landing is one blow taken at the PLAIN rate (a worn shield braces its damage, never its Defense XP), it costs its
  -- caster a whole windup with no swing, and it restarts the swing clock. So the bound holds while the least windup x the block multiple
  -- covers the swing interval; under that, an honest settle of a spell ground is refused value_over. Executed on the rows just written.
  if public.hr_hunt_limit('spell_windup_min_ms') is null or public.hr_hunt_limit('block_mult') is null
     or public.hr_hunt_limit('spell_windup_min_ms') * public.hr_hunt_limit('block_mult') < public.hr_hunt_limit('swing_interval_ms') then
    raise exception 'the least spell windup (%) x block_mult (%) is under the swing interval (%): a spell''s blows outrun the Defense bound',
      public.hr_hunt_limit('spell_windup_min_ms'), public.hr_hunt_limit('block_mult'), public.hr_hunt_limit('swing_interval_ms'); end if;
  -- THE AREA ABILITIES AND THE PARTY HEALS (2027-04-15; src/data/abilities.js AREA_TARGETS and target 'party'): each is in the bar's vocabulary,
  -- active, on the lane, disciplines, rune and ammo the data names, so the bar check accepts a slot naming one (Turning Cut, Raking Shot,
  -- Hoarfrost and Spring Tide among them).
  select want.ability_id into v_t from (values
    ('circle_of_renewal', 'heal', array['restoration']::text[], 'chalked_water_rune', 0),
    ('fireball', 'offense', array['destruction']::text[], 'chalked_fire_rune', 0),
    ('flame_volley', 'offense', array['ranged']::text[], 'chalked_fire_rune', 3),
    ('frost_slam', 'support', array['shield']::text[], 'chalked_ice_rune', 0),
    ('gash', 'offense', array['dual_axe']::text[], 'chalked_rupture_rune', 0),
    ('green_sickness', 'offense', array['restoration']::text[], 'chalked_poison_rune', 0),
    ('hoarfrost', 'offense', array['destruction']::text[], 'chalked_ice_rune', 0),
    ('raking_shot', 'offense', array['ranged']::text[], null::text, 2),
    ('shelter', 'support', array['shield']::text[], 'chalked_earth_rune', 0),
    ('spring_tide', 'heal', array['restoration']::text[], 'chalked_water_rune', 0),
    ('turning_cut', 'offense', array['club', 'dual_axe', 'sword']::text[], null::text, 0)
  ) want (ability_id, lane, disciplines, rune, ammo)
   where not exists (select 1 from public.hr_hunt_abilities a where a.ability_id = want.ability_id and a.active and a.lane = want.lane
                       and a.disciplines = want.disciplines and a.rune is not distinct from want.rune and a.ammo = want.ammo)
   order by 1 limit 1;
  if v_t is not null then raise exception 'the area ability % is not in hr_hunt_abilities as the data names it', v_t; end if;
  -- CALL OUT, THE MONEY LINE: every called room stands only on rows that pay no XP or coin, only its boss drops (his win's, Tyler 2026-11-14), its rows reach
  -- no roster and no other ground, and it has its travel and its ground.
  if exists (select 1 from public.hr_boss_calls c
              where not exists (select 1 from public.hr_hunt_grounds g where g.hunt_id = c.hunt_id)
                 or not exists (select 1 from public.hr_hunt_travel t where t.hunt_id = c.hunt_id and not t.training)
                 or exists (select 1 from public.hr_hunt_ground_spawns s join public.hr_hunt_kill_bounds b on b.monster_id = s.monster_id
                             where s.hunt_id = c.hunt_id and (b.gold_max <> 0 or b.xp_max <> 0 or (b.drops <> '{}'::jsonb and s.monster_id <> c.monster_id)))
                 or exists (select 1 from public.hr_hunt_roster o where o.monster_id = c.monster_id)
                 or exists (select 1 from public.hr_hunt_ground_spawns s where s.monster_id = c.monster_id and s.hunt_id <> c.hunt_id)) then
    raise exception 'a called room pays, or its row reaches a normal hunt'; end if;
  -- WHAT THE PAGE SAYS A WIN CAN DROP IS WHAT THE SETTLE LETS IT DROP: each call's listed ids are exactly its kill bound's, each with whole odds.
  if exists (select 1 from public.hr_boss_calls c join public.hr_hunt_kill_bounds b on b.monster_id = c.monster_id
              where (select coalesce(jsonb_agg(d.value->>'item' order by d.value->>'item'), '[]'::jsonb) from jsonb_array_elements(c.drops) d)
                    is distinct from (select coalesce(jsonb_agg(k order by k), '[]'::jsonb) from jsonb_object_keys(b.drops) k)
                 or exists (select 1 from jsonb_array_elements(c.drops) d
                             where jsonb_typeof(d.value->'ppm') is distinct from 'number' or (d.value->>'ppm') !~ '^[0-9]{1,7}$' or (d.value->>'ppm')::int not between 1 and 1000000)) then
    raise exception 'a call lists a drop its kill bound does not hold, or odds that are not whole parts per million'; end if;
  -- NATURAL WINS BEFORE THE CALL (lane/c-entry-gates): each call's count is the data's one number, on a boss its press's ground fields (so a normal hunt
  -- there is what counts it), never on a called row.
  if exists (select 1 from public.hr_boss_calls c
              where c.wins is distinct from 10
                 or not exists (select 1 from public.hr_hunt_ground_spawns s where s.hunt_id = c.from_hunt and s.monster_id = c.boss_id)
                 or exists (select 1 from public.hr_hunt_ground_spawns s where s.monster_id = c.boss_id and s.hunt_id = c.hunt_id)) then
    raise exception 'a call''s natural wins are not the data''s, or are counted on a boss its press''s ground does not field'; end if;
  -- CALL OUT COSTS STAMINA ONLY (Tyler 2026-11-20, balance call 22-8): no call charges gold a fight (the data refuses a fee: gen-hunt-sessions.mjs).
  if exists (select 1 from public.hr_boss_calls c where c.fight_fee <> 0) then
    raise exception 'a call charges gold a fight (Tyler 2026-11-20: Call out costs stamina only)'; end if;
  -- COMBAT TRAINING, THE MONEY LINE: every training ground stands in hr_hunts and hr_hunt_travel with one seat and the dummy alone; the dummy's bound
  -- pays no coin and no drop; no other ground fields it and no roster names it.
  if exists (select 1 from public.hr_training_grounds t
              where not exists (select 1 from public.hr_hunt_grounds g where g.hunt_id = t.hunt_id and g.seats = 1 and g.pockets = 1 and g.spawns = 1)
                 or not exists (select 1 from public.hr_hunt_travel v where v.hunt_id = t.hunt_id and not v.training)
                 or not exists (select 1 from public.hr_hunts h where h.hunt_id = t.hunt_id)
                 or exists (select 1 from public.hr_hunt_ground_spawns s where s.hunt_id = t.hunt_id and s.monster_id <> 'yard_dummy'))
     or exists (select 1 from public.hr_hunt_kill_bounds b where b.monster_id = 'yard_dummy' and (b.gold_max <> 0 or b.drops <> '{}'::jsonb or b.xp_max < 1))
     or not exists (select 1 from public.hr_hunt_kill_bounds b where b.monster_id = 'yard_dummy')
     or exists (select 1 from public.hr_hunt_ground_spawns s where s.monster_id = 'yard_dummy'
                  and not exists (select 1 from public.hr_training_grounds t where t.hunt_id = s.hunt_id))
     or exists (select 1 from public.hr_hunt_roster o where o.monster_id = 'yard_dummy')
     or exists (select 1 from public.hr_hunt_travel v where v.hunt_id = 'yard_dummy') then
    raise exception 'a training ground holds more than its dummy, or the dummy pays, or it stands where it trains nobody'; end if;
  -- THE TRAINING ITEMS, THE MONEY LINE (Tyler 2026-11-14: Crowns-bought goods never trade): every item is its own hr_items row of kind 'training'
  -- and trains a skill a ground trains; a bound row is untradeable, worth nothing, with no gold price and no shop bid; a gold row trades at its
  -- price / 100 as book, and the shop bids at most half its price (buying one to sell it back never pays).
  if exists (select 1 from public.hr_training_gear g
              where not exists (select 1 from public.hr_items i where i.item_id = g.item_id and i.kind = 'training')
                 or not exists (select 1 from public.hr_training_grounds t where t.skill = g.skill)
                 or g.hours_ms % 3600000 <> 0
                 or (g.bound and (exists (select 1 from public.hr_items i where i.item_id = g.item_id and (i.tradeable or i.value <> 0))
                                  or exists (select 1 from public.hr_hunt_vendor_value v where v.item_id = g.item_id)))
                 or (not g.bound and (not exists (select 1 from public.hr_items i where i.item_id = g.item_id and i.tradeable and i.value = g.price / 100)
                                      or not exists (select 1 from public.hr_hunt_vendor_value v where v.item_id = g.item_id and v.unit * 2 <= g.price))))
     or exists (select 1 from public.hr_items i where i.kind = 'training' and not exists (select 1 from public.hr_training_gear g where g.item_id = i.item_id)) then
    raise exception 'a training item is not its catalogue row, a bound one trades or is worth something, or a gold one sells back for more than half'; end if;
  -- KEYED HALLS: every hall stands in hr_hunts, hr_hunt_travel and hr_hunt_grounds (one pocket), its boss among its spawns and on no other ground,
  -- its key a catalogued item, and every row in its room a paying one (a called row never stands in a hall: the kill bounds' CHECK tells them apart).
  if exists (select 1 from public.hr_boss_halls h
              where not exists (select 1 from public.hr_hunt_grounds g where g.hunt_id = h.hunt_id and g.pockets = 1)
                 or not exists (select 1 from public.hr_hunt_travel t where t.hunt_id = h.hunt_id and not t.training)
                 or not exists (select 1 from public.hr_hunts u where u.hunt_id = h.hunt_id)
                 or not exists (select 1 from public.hr_items i where i.item_id = h.key_item)
                 or not exists (select 1 from public.hr_hunt_ground_spawns s where s.hunt_id = h.hunt_id and s.monster_id = h.monster_id)
                 or exists (select 1 from public.hr_hunt_ground_spawns s where s.monster_id = h.monster_id and s.hunt_id <> h.hunt_id)
                 or exists (select 1 from public.hr_hunt_ground_spawns s where s.hunt_id = h.hunt_id and s.monster_id ~ '_called$')
                 or exists (select 1 from public.hr_boss_calls c where c.hunt_id = h.hunt_id)) then
    raise exception 'a keyed hall is missing its room, its travel, its key or its boss, or a called row stands in it'; end if;
  -- Every supply, vendor value, ability rune and login reward is a catalogued item;
  -- every named hunt and ground hunt is in hr_hunts; every training id is a
  -- non-boss combat target; every ground spawn has a kill bound.
  if exists (select 1 from public.hr_hunt_supplies s where not exists (select 1 from public.hr_items i where i.item_id = s.item_id))
     or exists (select 1 from public.hr_hunt_vendor_value v where not exists (select 1 from public.hr_items i where i.item_id = v.item_id))
     or exists (select 1 from public.hr_hunt_abilities a where a.active and a.rune is not null
                  and not exists (select 1 from public.hr_items i where i.item_id = a.rune))
     or exists (select 1 from public.hr_premium_login_reward l where l.item_id is not null
                  and not exists (select 1 from public.hr_items i where i.item_id = l.item_id)) then
    raise exception 'a supply, vendor-value, ability-rune or login-reward row names an item hr_items does not have'; end if;
  -- (the Burning Tower's hunt joins hr_hunts only once its one door stands, 2027-05-02-tower-hunts-catalogue.generated.sql, after
  --  2027-04-24-tower-climb.sql: until then the ordinary door's gate refuses what hr_hunts does not name)
  if exists (select 1 from public.hr_hunt_travel t where not t.training and t.hunt_id <> all (array['the_burning_tower', 'unmarked_bone_wing', 'unmarked_flooded_wing']::text[])
               and not exists (select 1 from public.hr_hunts h where h.hunt_id = t.hunt_id))
     or exists (select 1 from public.hr_hunt_grounds g where g.hunt_id <> all (array['the_burning_tower', 'unmarked_bone_wing', 'unmarked_flooded_wing']::text[])
                  and not exists (select 1 from public.hr_hunts h where h.hunt_id = g.hunt_id)) then
    raise exception 'a named hunt or a ground hunt is not in hr_hunts'; end if;
  if exists (select 1 from public.hr_hunt_travel t where t.training
               and not exists (select 1 from public.hr_activities a
                                where a.kind = 'combat' and a.activity_id = t.hunt_id and not a.is_boss)) then
    raise exception 'a training id in hr_hunt_travel is not a non-boss combat target'; end if;
  if exists (select 1 from public.hr_hunt_ground_spawns s
               where not exists (select 1 from public.hr_hunt_kill_bounds b where b.monster_id = s.monster_id)) then
    raise exception 'a ground spawns a monster with no kill bound'; end if;
  -- THE DROP BOUNDS (2027-02-10, the Brook Bear): every item a monster of a ground can drop (src/data/monsters.js
  -- over each pocket's whole pack) has, on that ground, the settle's OWN item bound (hr_hunt_apply_instance (4c):
  -- the most rows naming it over the kill bounds of the ground's spawn rows) at least the rows one kill names it.
  -- A 0 here is a hunt the settle refuses value_over on the first such drop.
  select d.hunt_id || ' ' || d.item_id into v_t from (values
    ('coppercap_warrens', 'big_bones', 1),
    ('coppercap_warrens', 'boarhide_belt', 1),
    ('coppercap_warrens', 'boarhide_body', 1),
